{
  "name": "海洋光学 OOI USB 通信组件",
  "name_en": "Ocean Optics OOI USB Communication Component",
  "manufacturer": "",
  "description": "这是一个非物理软件组件，用于实验软件中与海洋光学光谱仪建立底层 USB 通信。它负责打开和关闭设备连接、发送 OOI 协议命令、发起查询并读取返回数据，供上层光谱采集与仪器控制逻辑调用。",
  "description_en": "This is a non-physical software component used in laboratory software to provide low-level USB communication with Ocean Optics spectrometers. It handles opening and closing the device connection, sending OOI-protocol commands, initiating queries, and reading returned data for higher-level acquisition and instrument-control logic.",
  "actions": [
    {
      "action_name": "auto-send_command",
      "description": "向设备发送一条 USB 命令消息。",
      "description_en": "Send a USB command message to the device."
    },
    {
      "action_name": "auto-innitiate_query",
      "description": "发起一次查询并发送查询负载。",
      "description_en": "Initiate a query and send the query payload."
    },
    {
      "action_name": "auto-receive_query",
      "description": "接收查询返回的数据，可使用默认或备用读取端点。",
      "description_en": "Receive the response data for a query, using the default or alternate read endpoint."
    },
    {
      "action_name": "auto-query",
      "description": "执行一次完整的查询事务，包括发送请求并接收响应。",
      "description_en": "Perform a complete query transaction by sending a request and receiving the response."
    },
    {
      "action_name": "auto-open_device",
      "description": "打开 USB 设备连接。",
      "description_en": "Open the USB device connection."
    },
    {
      "action_name": "auto-is_open",
      "description": "检查 USB 设备连接是否已打开。",
      "description_en": "Check whether the USB device connection is open."
    },
    {
      "action_name": "auto-close_device",
      "description": "关闭 USB 设备连接。",
      "description_en": "Close the USB device connection."
    },
    {
      "action_name": "auto-usb_send",
      "description": "通过底层 USB 通道发送原始数据。",
      "description_en": "Send raw data through the low-level USB channel."
    },
    {
      "action_name": "auto-usb_read_lowspeed",
      "description": "从低速 USB 读取端点读取数据。",
      "description_en": "Read data from the low-speed USB endpoint."
    },
    {
      "action_name": "auto-usb_read_highspeed",
      "description": "从高速 USB 读取端点读取数据。",
      "description_en": "Read data from the high-speed USB endpoint."
    },
    {
      "action_name": "auto-usb_read_highspeed_alt",
      "description": "从备用高速 USB 读取端点读取数据。",
      "description_en": "Read data from the alternate high-speed USB endpoint."
    },
    {
      "action_name": "auto-set_default_read",
      "description": "设置默认的 USB 读取方式。",
      "description_en": "Set the default USB read method."
    }
  ],
  "tag_hints": [
    "USB spectrometer communication",
    "Ocean Optics",
    "OOI protocol",
    "spectrometer software interface",
    "USB endpoint read/write",
    "query-response messaging"
  ]
}

